// PII-Schutz: Aufgaben-Inhalte duerfen NIE an ein :cloud-Modell (routet auf ollama.com).
const body = $input.first().json.body || {};
const model = String(body.model || '');
if (!model) {
  throw new Error('Kein Modell angegeben.');
}
if (model.includes(':cloud')) {
  throw new Error('PII-Schutz: Cloud-Modell "' + model + '" ist fuer Aufgaben-Inhalte verboten.');
}
if (!body.prompt || !body.callbackUrl || !body.jobKey || !body.taskId) {
  throw new Error('Unvollstaendige Nutzlast (prompt/callbackUrl/jobKey/taskId).');
}
return $input.all();

// Ollama /api/generate liefert { response: "<json-string>", ... }.
// Den JSON-String parsen und den Callback-Body bauen. Bei Unsinn: abbrechen (kein Callback).
const webhook = $('Webhook').first().json.body;
const roh = $input.first().json.response;
let parsed;
try {
  parsed = JSON.parse(roh);
} catch (e) {
  throw new Error('Ollama-Antwort ist kein JSON: ' + String(roh).slice(0, 200));
}
return [{
  json: {
    callbackUrl: webhook.callbackUrl,
    callbackSecret: webhook.callbackSecret,
    payload: {
      jobKey: webhook.jobKey,
      taskId: webhook.taskId,
      important: parsed.important,
      urgent: parsed.urgent,
      confidence: parsed.confidence,
      reasoning: parsed.reasoning,
    },
  },
}];
